// Sample form submissions (replaces Typeform/Webflow). Messy on purpose: spacing, casing, duplicate, bad email.
const leads = [
  { name: '  daniel RUIZ ', email: 'Daniel@RuizDental.example ', phone: '(512) 555-0142', company: 'Ruiz Dental', budget: '$3,000 - 5,000', timeline: 'this month', message: 'Appointment reminders and review requests across 3 clinics.' },
  { name: 'priya n', email: 'priya.n@example.com', phone: '', company: '', budget: 'not sure', timeline: 'someday', message: 'Just curious what AI can do.' },
  { name: 'Tom Becker', email: 'tom@beckerlog.example', phone: '+1 646 555 0199', company: 'Becker Logistics', budget: '$10k+', timeline: 'ASAP', message: 'Dispatch team copies data from emails into our TMS all day.' },
  { name: 'Emily Chen', email: 'emily@chenbakery.example', phone: '415.555.0123', company: 'Chen Bakery', budget: '<$500', timeline: 'next quarter', message: 'Want an Instagram auto-poster.' },
  { name: 'TOM BECKER', email: ' tom@beckerlog.example', phone: '', company: 'Becker Logistics', budget: '$10k+', timeline: 'ASAP', message: 'Sent the form twice, sorry!' },
  { name: 'Mark', email: 'mark@@broken', phone: '', company: '', budget: '$2000', timeline: 'this month', message: 'test' },
];
return leads.map(l => ({ json: { ...l, source: 'sample' } }));

// Formatter step: clean every field the way Zapier Formatter would (free in Zapier, free here too).
const title = s => (s || '').trim().toLowerCase().replace(/\b\w/g, c => c.toUpperCase()).replace(/\s+/g, ' ');
const money = s => {
  const t = String(s || '').toLowerCase().replace(/,/g, '');
  const m = t.match(/(\d+(?:\.\d+)?)\s*(k)?/);
  if (!m) return null;
  return Number(m[1]) * (m[2] ? 1000 : 1);
};
const phone = s => {
  const d = String(s || '').replace(/\D/g, '');
  if (!d) return null;
  if (d.length === 10) return '+1' + d;          // US local number
  return '+' + d;
};
const urgentWords = ['asap', 'this month', 'this week', 'next month'];
return $input.all().map(({ json: raw }) => {
  const j = raw.body ?? raw;                        // webhook payloads arrive under body
  const timeline = String(j.timeline || '').trim().toLowerCase();
  return { json: {
    name: title(j.name),
    email: String(j.email || '').trim().toLowerCase(),
    phone: phone(j.phone),
    company: (j.company || '').trim() || null,
    budget_raw: j.budget || null,
    budget_min: money(j.budget),
    timeline,
    is_urgent: urgentWords.includes(timeline),
    message: (j.message || '').trim(),
    source: raw.source || 'webhook',
    received_at: new Date().toISOString(),
  } };
});

// Validate emails, drop duplicates, decide who is a hot lead.
const seen = new Set();
const out = [];
for (const { json: l } of $input.all()) {
  const validEmail = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(l.email);
  if (!validEmail) continue;                 // in production: route to an "invalid" log instead
  if (seen.has(l.email)) continue;           // duplicate submission
  seen.add(l.email);
  const qualified = (l.budget_min ?? 0) >= 1000 && l.is_urgent;
  out.push({ json: { ...l, qualified, reason: qualified ? `Budget from $${l.budget_min}, timeline "${l.timeline}"` : 'Below budget or no urgency' } });
}
return out;
